import java.io.*;import java.util.*;import java.util.stream.*;import static java.util.stream.Collectors.toList;class Result {public static int surfaceArea(List<List<Integer>> A) {int H = A.size();int W = A.get(0).size();int area = 0;for (int i = 0; i < H; i++) {for (int j = 0; j < W; j++) {int h = A.get(i).get(j);if (h > 0) {area += 2;int up = (i > 0) ? A.get(i - 1).get(j) : 0;int down = (i < H - 1) ? A.get(i + 1).get(j) : 0;int left = (j > 0) ? A.get(i).get(j - 1) : 0;int right = (j < W - 1) ? A.get(i).get(j + 1) : 0;area += Math.max(0, h - up);area += Math.max(0, h - down);area += Math.max(0, h - left);area += Math.max(0, h - right);}}}return area;}}public class Solution {public static void main(String[] args) throws IOException {BufferedReader bufferedReader = new BufferedReader(new InputStreamReader(System.in));BufferedWriter bufferedWriter = new BufferedWriter(new OutputStreamWriter(System.out));String[] firstMultipleInput = bufferedReader.readLine().replaceAll("\\s+$", "").split(" ");int H = Integer.parseInt(firstMultipleInput[0]);int W = Integer.parseInt(firstMultipleInput[1]);List<List<Integer>> A = new ArrayList<>();IntStream.range(0, H).forEach(i -> {try {A.add(Stream.of(bufferedReader.readLine().replaceAll("\\s+$", "").split(" ")).map(Integer::parseInt).collect(toList()));} catch (IOException ex) {throw new RuntimeException(ex);}});int result = Result.surfaceArea(A);bufferedWriter.write(String.valueOf(result));bufferedWriter.newLine();bufferedReader.close();bufferedWriter.close();}}